class UserActivityLogExportApiTests(APITestCase):
    def test_requires_authentication(self):
        response = self.client.get("/api/v1/users/me/activity-log/export/")
        self.assertEqual(response.status_code, status.HTTP_401_UNAUTHORIZED)

    def _csv_rows(self, response):
        import csv
        import io

        content = b"".join(response.streaming_content).decode()
        return list(csv.reader(io.StringIO(content)))

    def test_export_scoped_to_own_user_with_correct_headers(self):
        user = _make_user()
        other = _make_user()
        UserActivityLog.objects.create(
            user=user,
            actor_user=user,
            category="CONFIGURATION",
            action="PROFILE_UPDATED",
            summary="You updated your profile.",
            activity_datetime=timezone.now(),
        )
        UserActivityLog.objects.create(
            user=other,
            actor_user=other,
            category="CONFIGURATION",
            action="PROFILE_UPDATED",
            summary="Someone else's activity.",
            activity_datetime=timezone.now(),
        )
        self.client.force_authenticate(user)

        response = self.client.get("/api/v1/users/me/activity-log/export/")
        self.assertEqual(response.status_code, status.HTTP_200_OK)
        self.assertEqual(response["Content-Type"], "text/csv")
        self.assertIn("attachment", response["Content-Disposition"])

        rows = self._csv_rows(response)
        self.assertEqual(
            rows[0], ["category", "action", "summary", "actor", "activity_datetime"]
        )
        summaries = [row[2] for row in rows[1:]]
        self.assertEqual(summaries, ["You updated your profile."])

    def test_category_filter_parity_with_list_endpoint(self):
        user = _make_user()
        UserActivityLog.objects.create(
            user=user,
            actor_user=user,
            category="CONFIGURATION",
            action="PROFILE_UPDATED",
            summary="Config change.",
            activity_datetime=timezone.now(),
        )
        UserActivityLog.objects.create(
            user=user,
            actor_user=user,
            category="COURSE",
            action="COURSE_ASSIGNED",
            summary="Course assigned to you.",
            activity_datetime=timezone.now(),
        )
        self.client.force_authenticate(user)

        response = self.client.get(
            "/api/v1/users/me/activity-log/export/", {"category": "COURSE"}
        )
        rows = self._csv_rows(response)
        summaries = [row[2] for row in rows[1:]]
        self.assertEqual(summaries, ["Course assigned to you."])

    def test_export_action_itself_is_logged(self):
        user = _make_user()
        self.client.force_authenticate(user)

        self.client.get("/api/v1/users/me/activity-log/export/")

        self.assertTrue(
            UserActivityLog.objects.filter(
                user=user, action=UserActivityActionEnums.ACTIVITY_LOG_EXPORTED
            ).exists()
        )


class KYCServiceTests(TestCase):
    def test_is_verified_false_with_no_submission(self):
        user = _make_user()

        self.assertFalse(kyc_service.is_verified(user=user))

    def test_is_verified_true_when_latest_is_approved(self):
        user = _make_user()
        kyc_service.submit_verification(
            user=user,
            country_of_issue="NG",
            document_type="NATIONAL_ID",
            id_number="12345",
            first_name="John",
            last_name="Doe",
            address="123 Main St",
            date_of_birth="1990-01-01",
        )
        KYCVerification.objects.filter(user=user).update(status=KYCStatus.APPROVED)

        self.assertTrue(kyc_service.is_verified(user=user))

    def test_cannot_submit_while_a_pending_submission_exists(self):
        user = _make_user()
        kyc_service.submit_verification(
            user=user,
            country_of_issue="NG",
            document_type="NATIONAL_ID",
            id_number="12345",
            address="123 Main St",
            date_of_birth="1990-01-01",
            first_name="John",
            last_name="Doe",
        )

        with self.assertRaises(ValidationError):
            kyc_service.submit_verification(
                user=user,
                country_of_issue="NG",
                document_type="VOTERS_ID",
                id_number="67890",
                address="123 Main St",
                date_of_birth="1990-01-01",
                first_name="John",
                last_name="Doe",
            )

    def test_can_resubmit_after_rejection(self):
        user = _make_user()
        kyc_service.submit_verification(
            user=user,
            country_of_issue="NG",
            document_type="NATIONAL_ID",
            id_number="12345",
            address="123 Main St",
            date_of_birth="1990-01-01",
            first_name="John",
            last_name="Doe",
        )
        KYCVerification.objects.filter(user=user).update(status=KYCStatus.REJECTED)

        resubmission = kyc_service.submit_verification(
            user=user,
            country_of_issue="NG",
            document_type="VOTERS_ID",
            id_number="67890",
            address="123 Main St",
            date_of_birth="1990-01-01",
            first_name="John",
            last_name="Doe",
        )

        self.assertEqual(resubmission.status, KYCStatus.PENDING)

    def test_require_verified_raises_when_not_verified(self):
        user = _make_user()

        with self.assertRaises(ValidationError):
            kyc_service.require_verified(user=user)

    def test_wrong_role_cannot_approve(self):
        applicant = _make_user()
        verification = kyc_service.submit_verification(
            user=applicant,
            country_of_issue="NG",
            document_type="NATIONAL_ID",
            id_number="12345",
            address="123 Main St",
            date_of_birth="1990-01-01",
            first_name="John",
            last_name="Doe",
        )
        wrong_role_reviewer = _make_user(role=UserRole.COURSE_CREATOR)

        with self.assertRaises(PermissionDenied):
            kyc_service.approve_verification(
                verification=verification, reviewer=wrong_role_reviewer
            )

    def test_wrong_role_cannot_reject(self):
        applicant = _make_user()
        verification = kyc_service.submit_verification(
            user=applicant,
            country_of_issue="NG",
            document_type="NATIONAL_ID",
            id_number="12345",
            address="123 Main St",
            date_of_birth="1990-01-01",
            first_name="John",
            last_name="Doe",
        )
        wrong_role_reviewer = _make_user(role=UserRole.CREATOR_REVIEWER)

        with self.assertRaises(PermissionDenied):
            kyc_service.reject_verification(
                verification=verification,
                reviewer=wrong_role_reviewer,
                rejection_reason="Blurry document.",
            )

    def test_admin_who_opted_out_is_not_notified(self):
        subscribed_admin = _make_user(role=UserRole.ADMIN)
        opted_out_admin = _make_user(role=UserRole.ADMIN)
        notification_preference_service.update_preference(
            user=opted_out_admin, kyc_submission_alert=False
        )
        user = _make_user()

        kyc_service.submit_verification(
            user=user,
            country_of_issue="NG",
            document_type="NATIONAL_ID",
            id_number="12345",
            address="123 Main St",
            date_of_birth="1990-01-01",
            first_name="John",
            last_name="Doe",
        )

        self.assertTrue(
            Notification.objects.filter(
                receiver=subscribed_admin, title="New KYC verification request"
            ).exists()
        )
        self.assertFalse(
            Notification.objects.filter(
                receiver=opted_out_admin, title="New KYC verification request"
            ).exists()
        )


